) AS v("handle", "award", "year", "position", "title", "source_url")
JOIN "public"."profiles" p ON p.handle = v.handle AND p.kind = 'bar'
-- An award already there under another spelling ("Best New Opening Award",
-- "The Best Bar in Japan") keeps its row.
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."profile_awards" b
    WHERE b.profile_id = p.id AND b.award = v.award AND b.year = v.year::smallint AND v.title IS NOT NULL
      AND lower(regexp_replace(regexp_replace(b.title, ' Award$', ''), '^The ', ''))
        = lower(regexp_replace(regexp_replace(v.title, ' Award$', ''), '^The ', ''))
)
-- Rows already there with the same wording are kept too.
ON CONFLICT DO NOTHING;

INSERT INTO "public"."profile_menu_editions" ("profile_id", "name", "year", "month", "theme", "drinks", "source_url")
SELECT p.id, v.name, v.year::smallint, v.month::smallint, v.theme, v.drinks, v.source_url
FROM (VALUES
    ('barleonehk', 'Opening menu (Cocktail Popolari)', 2023, 6, 'Launch list of affordable, simple Italian-leaning classics in the spirit of a Roman neighbourhood bar.', ARRAY['Leone Martini']::text[], 'https://www.the50.com/stories/News/bar-leone-opening-hong-kong.html'),
    ('handshake_bar', 'Menu Handshake (2024 list)', 2024, 5, 'Signature list split into Miniature Classics, First Round and Out Spoken Flavours, plus tea champagnes and alcohol-free serves.', ARRAY['Mini Martini', 'Dirty Martini', 'Mezcal Negroni', 'Espresso Martini', 'Piña Colada', 'Guava + Jasmin', 'Earl Grey', 'El Santo', 'Coconut + Tarragon', 'Olive & Apple', 'Once Upon a Time in Oaxaca', 'Matcha Yuzu', 'Mexi-Thai', 'Vi-No', 'Orange Blossom', 'Cariño', 'Cacao Negroni', 'Fig Martini', 'Butter Mushroom Old Fashioned']::text[], 'http://web.archive.org/web/20240503071310/https://handshake.bar/menu-handshake/'),
    ('handshake_bar', 'Menu Handshake (2025 list)', 2025, 6, 'Reworked signature list in the same sections, adding highballs and richer martini-style drinks alongside house favourites.', ARRAY['Mini Dirty Martini', 'Mezcal Negroni', 'Espresso Martini', 'Gin & Juice', 'Piña Colada', 'Lychee Highball', 'Once Upon in Oaxaca', 'Earl Grey', 'Olive Oil Gimlet', 'Matcha Yuzu', 'Mexi-Thai', 'Matcha Martini', 'Match Made in Heaven', 'Orange Blossom', 'Cariño', 'Fig Martini', 'Butter Mushroom Old Fashioned']::text[], 'http://web.archive.org/web/20250624225817/https://handshake.bar/menu-handshake/'),
    ('sips.barcelona', 'Opening menu', 2021, 8, 'Debut list of fixed classics plus creative signatures built on temperature and texture play, set to rotate quickly.', ARRAY['Bubble', 'Espresso Martini', 'Queen']::text[], 'https://www.gastronomistas.com/sips-nueva-cocteleria-vanguardia-barcelona/'),
    ('sips.barcelona', 'Esencia tasting menu', 2024, 1, 'Liquid tasting menu in a back room: eight small sips in four themed sequences, promised to change every three months.', '{}'::text[], 'https://www.timeout.es/barcelona/es/noticias/asi-es-el-nuevo-espacio-y-menu-degustacion-liquido-de-la-mejor-cocteleria-del-mundo-que-esta-en-barcelona-011924'),
    ('paradiso_barcelona', 'Opening menu', 2015, NULL, 'Launch list of 24 drinks pairing classic cocktails with Giannotti''s modern versions of each.', ARRAY['The Great Gatsby']::text[], 'https://en.ara.cat/food/the-bar-that-has-been-making-the-best-cocktails-in-the-world-for-10-years-in-barcelona-s-born-district_1_5643213.html'),
    ('paradiso_barcelona', 'New menu (backlit menu)', 2018, 3, 'Theatrical new list in a backlit menu format, keeping only three earlier drinks.', ARRAY['Supercool Martini', 'Caballo de Troya', 'Where is the Daiquiri', 'Great Gatsby', 'Mediterranean Treasure', 'Punch in a bottle']::text[], 'https://bcnfoodieguide.com/paradiso-nueva-sorprendente-carta/'),
    ('paradiso_barcelona', 'Magic and illusion menu', 2019, 6, '21 new cocktails themed on magic and illusionism, with six house classics kept from before.', ARRAY['Guillotina', 'Gelato Paradiso', 'Kriptonita', 'Magic Wizard', 'Mediterranean Treasure', 'Supercool Martini']::text[], 'https://neodrinks.com/secretos-nueva-carta-cocteles-paradiso-2019/'),
    ('paradiso_barcelona', '2021-2022 menu', 2021, NULL, 'The menu that ran through 2021 and 2022; The Cloud was created for it.', ARRAY['The Cloud']::text[], 'https://en.ara.cat/food/the-bar-that-has-been-making-the-best-cocktails-in-the-world-for-10-years-in-barcelona-s-born-district_1_5643213.html'),
    ('paradiso_barcelona', 'The Evolution', 2022, 9, '14 new drinks each tied to a milestone in human progress, from fire and the wheel to penicillin and space travel.', ARRAY['On Fire', 'Copper', 'Fleming', 'Supercool Martini', 'The Cloud']::text[], 'https://barmag.fr/evolution-un-hommage-a-levolution-de-lhumanite-paradiso-barcelone/'),
    ('paradiso_barcelona', 'Mysteries of the World', 2024, 5, '15 new cocktails inspired by unsolved mysteries, from the pyramids and the Great Flood to fungi and the human brain.', ARRAY['Enigma', 'Revival Negroni', 'Secret of Java', 'Messenja', 'Mediterranean Treasure', 'Great Gatsby', 'Kriptonita', 'Supercool Martini', 'The Cloud', 'On Fire']::text[], 'https://www.bargiornale.it/spirit/mysteries-of-the-world-il-nuovo-menu-del-paradiso-di-barcellona/'),
    ('paradiso_barcelona', 'Oltre', 2026, 6, 'Surrealism-led list inspired by Dali and Miro: 18 new signatures (four alcohol-free) plus seven returning house classics.', ARRAY['Alba', 'Source', 'Piccolo e Grande', 'Fantasy', 'Pimpollo', 'Illusion', 'Gala Colada', 'Somni', 'Wabi-Sabi', 'Crudo', 'Perception', 'Asparagus', 'Selva', 'Eco', 'Ritual', 'Melt', 'Origen']::text[], 'https://barmagazine.com/paradiso-barcelona-oltre-cocktail-menu'),
    ('tayer_elementary', 'Opening menus (Elementary and Tayer)', 2019, NULL, 'Front bar of pre-batched twists on classics; back bar drinks named after their key ingredient and made to order.', ARRAY['Whey Sour', 'Palo Santo Gimlet', 'Nordic Old Fashioned', 'Elementary Frozen Coffee']::text[], 'https://www.hot-dinners.com/Gastroblog/Test-drive/tayer-elementary-review-london-cocktail-bar-restaurant-old-street-ta-ta-eatery'),
    ('tayer_elementary', 'Casual by Tayer (residency menu)', 2026, 7, 'Six-week pop-up list at Cato while the Old Street bar was closed after a fire, mixing Tayer style with Elementary precision.', ARRAY['One Sip Martini']::text[], 'https://drinksint.com/tayer-elementary-opens-new-temporary-bar-casual/'),
