    ('abarwithshapesforaname', 'Neue Menu', 2026, 9, 'New list with many drinks named after modernist artists and designers, keeping a few favourites from the previous menu.', ARRAY['Core', 'Bogler', 'Soffiten', 'Aalto', 'Warp/Weft', 'バター割り', 'Pastel', 'Albers', 'Miguelito', 'Kazimir', 'Atlas', 'Toreador']::text[], 'https://drive.google.com/file/d/15PbzJcI98ZZlYlty_xZE6F9jPVP2nTM9/view'),
    ('waltzbar', 'Opening menu: In Season and Evergreen', 2025, NULL, 'Japanese-style list split into a rotating micro-season section, with new drinks added weekly, and a steadier Evergreen section of technique-led drinks.', ARRAY['Jerusalem Artichoke', 'Waltz Vodka Soda']::text[], 'https://www.diffordsguide.com/bars/5BNrP5/waltz'),
    ('sidehustlelondon', 'Opening menu', 2021, 5, 'British-pub-meets-Mexico bar in a former police station, with an agave-focused cocktail list.', '{}'::text[], 'https://www.thespiritsbusiness.com/2022/10/nomad-from-new-york-to-london/'),
    ('sidehustlelondon', 'Spring 2022 menu', 2022, 5, 'Spring list sectioned by style, mixing agave classics with seasonal, low-waste signatures that nod to the bar''s Mexican influences.', ARRAY['Classic Margarita', 'Seasonal Margarita', 'Paloma', 'Michelada', 'Batanga', 'Oaxacan Old Fashioned', 'Seoul Mate', 'English Heat', 'Sergeant Pepper', 'Start Me Up', 'Walter Gibson', 'North Sea Oil', 'Hustle & Flow', 'Ma Cherie', 'Pink Elephant', 'Fresa y Cerveza', 'Oliva', 'Pandan Negroni']::text[], 'https://web.archive.org/web/20220509205144/https://www.thenomadhotel.com/wp-content/uploads/2022/05/09095352/09.05.22-SIDE-HUSTLE.pdf'),
    ('sidehustlelondon', 'Autumn 2023 menu', 2023, 9, 'Refreshed signatures alongside the house margaritas, paloma and michelada, with new agave and pisco drinks.', ARRAY['Seasonal Margarita', 'Paloma', 'Michelada', 'Toreador', 'Batanga', 'Oaxacan Old Fashioned', 'Clip Joint Cup', 'Stranger Things', 'Sergeant Pepper', 'Walter Gibson', 'Spring Sting', 'Mango Jerry', 'Taking The Pisco', 'Pink Elephant', 'Pardon Plea', 'Pandan Negroni', 'Black Dahlia', 'Panamexicano']::text[], 'https://web.archive.org/web/20230923115706/https://www.thenomadhotel.com/wp-content/uploads/2023/09/01152038/01.09.23-SIDE-HUSTLE-DINNER.pdf'),
    ('americanbarsavoy', 'The London Menu', 2016, 1, '24 drinks, four for each of the six boroughs around the hotel, telling London stories with illustrations and a short film.', ARRAY['Pickering Place', 'Green Park', 'Punk Rock']::text[], 'https://www.thespiritsbusiness.com/2016/01/savoys-american-bar-announces-london-inspired-cocktail-menu/'),
    ('americanbarsavoy', 'Coast To Coast', 2017, 4, 'A south-to-north journey across Britain, from Kent to Edinburgh, each region with its own ingredients and serving vessels.', '{}'::text[], 'https://www.thespiritsbusiness.com/2017/04/the-savoys-american-bar-captures-britain-with-cocktails/'),
    ('americanbarsavoy', 'Every Moment Tells A Story', 2018, 4, 'Drinks built around 20 Terry O''Neill photographs of celebrities at the Savoy that hang on the bar''s walls.', ARRAY['Behind Closed Doors', 'The Googly', 'Pinstripe', 'That''s A Wrap', 'Capturing The Moment To Share']::text[], 'https://www.thespiritsbusiness.com/2018/04/the-savoys-american-bar-captures-iconic-stars-in-cocktails/'),
    ('americanbarsavoy', 'The Savoy Songbook', 2019, 4, '20 drinks laid out like an album track list, each tied to a song played in the bar, released alongside a live piano album.', ARRAY['Somewhere Sailin''', 'Sun Sun Sun', 'I Love You', 'Electric Lover', 'Breathless Charm', 'Window into Paradise']::text[], 'https://www.thespiritsbusiness.com/2019/03/savoys-american-bar-debuts-music-led-cocktails/'),
    ('americanbarsavoy', 'Reopening menu (Shannon Tebay)', 2021, 10, 'Short post-lockdown list from the bar''s first American and first female head bartender in a century, focused on sustainability.', '{}'::text[], 'https://drinksint.com/the-american-bar-at-the-savoy-set-to-reopen/'),
    ('americanbarsavoy', 'Re:Invented', 2022, 5, 'Modern reworkings of well-known and forgotten Savoy classics, including Harry Craddock recipes, with seasonal and low-waste twists.', ARRAY['Spring Is In The Air', 'To The Moon & Back', 'The Passing Torch', 'Platinum Punch']::text[], 'https://www.thespiritsbusiness.com/2022/05/american-bar-unveils-new-cocktail-menu/'),
    ('americanbarsavoy', 'The Savoy: American Bar Journal', 2023, 5, 'Menu styled after the Savoy Cocktail Book, logging moments past and present as drinks, ordered by flavour with an index of stories.', ARRAY['New York Cherub', 'Coffee Black Velvet', 'Homecoming', 'Fine & Fancy']::text[], 'https://www.thespiritsbusiness.com/2023/05/american-bar-debuts-new-menu/'),
    ('americanbarsavoy', 'Liquid Moments', 2025, 1, '17 drinks for the Savoy''s 135th anniversary, each based on a story from the hotel''s history.', ARRAY['A Touch of Pink', 'Since 1986', 'New Heights', 'Painter''s Palette', 'Red Carpet']::text[], 'https://www.thespiritsbusiness.com/2025/02/the-savoys-american-bar-unveils-new-menu/'),
    ('lyanessbar', 'Opening menu', 2019, 3, 'Ingredient-led list replacing Dandelyan: house-made core ingredients such as Infinite Banana, Purple Pineapple and Onyx, each with three suggested drinks.', '{}'::text[], 'https://www.thespiritsbusiness.com/2019/10/lyaness-menu-highlights-new-core-ingredients/'),
    ('lyanessbar', 'Ingredient Slayer', 2019, 10, '21 drinks built on seven core ingredients, adding Golden Levain, Tea-mooth, Vegan Honey and Peach Emoji to the original three.', '{}'::text[], 'https://drinksint.com/new-menu-game-changer-for-lyaness/'),
    ('lyanessbar', 'Lyaness British Cookbook', 2021, 11, '15 drinks around five new ingredients that read global flavours through a British lens, such as Oyster Honey and Blood Curaçao.', ARRAY['Marygold Gimlet', 'Blood Brown Derby', 'Chestnut Rabble']::text[], 'https://www.thespiritsbusiness.com/2021/11/lyaness-takes-cookery-inspired-approach-to-new-menu/'),
    ('lyanessbar', 'The Ancestral Cookbook', 2022, 11, '15 drinks in five themes about how food shaped human evolution and culture, built on ingredients like Everything Vinegar and Thunder Mushroom.', ARRAY['CC Mizuwari', 'The Goldblum Whiptail']::text[], 'https://www.thespiritsbusiness.com/2022/11/preview-lyaness-ancestral-cookbook-menu/'),
    ('lyanessbar', '3.0 Cookbook', 2024, 3, 'Final cookbook menu: 15 stripped-back drinks explaining flavour and the stories behind the bar''s bespoke ingredients.', ARRAY['Forbidden Cola', 'Kentakki Fried Cocktail']::text[], 'https://www.thespiritsbusiness.com/2024/03/lyaness-to-launch-new-cocktail-menu/'),
    ('lyanessbar', 'Collaboration Menu', 2025, 3, 'First of a series on cooperation, drawing on examples from history and around the world where working together created something new.', '{}'::text[], 'https://web.archive.org/web/20250318074735/https://www.lyaness.com/'),
    ('lyanessbar', 'Collaboration 2.0', 2026, 6, 'Second collaboration menu, about ideas and ways of thinking that changed the team''s approach, each drink tied to a story from science or history.', ARRAY['Pink Belly Gimlet', 'Cherry Cannon Punch', 'Lobster Frappé', 'Iron Mai Tai', 'Heart Yard Highball', 'Ray Cat', 'Lunar Tuxedo', 'Royal Gambit', 'Forty-Fruit Hook', 'Rainwater Fix']::text[], 'https://www.lyaness.com/'),
    ('officialcafepacifico', 'Drinks Menu, June 2026', 2026, 6, 'Margarita-led house list of a restaurant open since 1982: classic, spicy, fruit and mid-strength margaritas by the glass or pitcher.', ARRAY['Pacifico Margarita', 'Leve Margarita', 'Picante Margarita', 'Fruit Margarita', 'Loba Margarita']::text[], 'https://cafe-pacifico.com/wp-content/uploads/2026/06/Cafe-Pacifico-Drinks-Menu-June-2026.pdf'),
    ('swiftsoho', 'Opening downstairs menu', 2016, 11, 'Whisky-leaning downstairs list of about 20 house drinks across all spirits, with a short aperitivo list upstairs.', ARRAY['The Fourth Gentleman', 'Yardbird', 'Curtain Call', 'New Lace', 'Silver Pistol', 'Praline Flip', 'Julep Américain', 'Shanghaied', 'Desert Rose', 'Amethyst', 'White Water', 'Ribbon', 'Liberty', 'Mountain Spring', 'Bazaar', 'The Prestige', 'Cobblestone', 'Amber Cane', 'Snowstorm', 'Irish Coffee']::text[], 'https://web.archive.org/web/20170401072416/http://www.barswift.com:80/menu/downstairs-cocktail-menu/'),
    ('swiftsoho', 'Downstairs menu, winter 2018-19', 2019, 1, 'New downstairs list of seasonal house drinks, from peanut-butter rum to sugar-snap fizz.', ARRAY['Tinderbox', 'Ice Maiden', 'Sterling', 'Serendade', 'Morelia''s Shadow', 'Horizon', 'Santa Fe', 'Pointer', 'Osiris', 'Pinwheel', 'Belltower', 'Droplet', 'Fairyland', 'Chameleon', 'Old Compton', 'Pembrook', 'Kiwi Bellini', 'Daylily Fizz']::text[], 'https://web.archive.org/web/20190124033618/http://www.barswift.com:80/menu/downstairs-cocktail-menu/'),
    ('swiftsoho', 'Downstairs menu, autumn 2019', 2019, 9, 'Refreshed downstairs list with lighter sparkling drinks and a pandan-coconut Japanese whisky serve.', ARRAY['Irish Coffee', 'Destination Tokyo', 'Caprini', 'Hedgerow', 'Ice Maiden', 'Bocatello', 'Mountain Spring', 'Tempest', 'Mahi Mahi', 'Everglade', 'Coral Reef', 'Shangaied', 'Droplet', 'Chameleon', 'Siren', 'Jackdaw', 'Anita', 'Cobblestone']::text[], 'https://web.archive.org/web/20190922165257/http://www.barswift.com/menu/downstairs-cocktail-menu/'),
    ('swiftsoho', 'Hospitality Menu', 2020, 3, '15 downstairs drinks about Soho''s heritage, people and places, from its music clubs and theatres to its coffee culture.', ARRAY['Flamingo All Nighter', 'Scala', 'Parakeet', 'Windmill', 'Irish Coffee']::text[], 'https://www.thespiritsbusiness.com/2020/03/swift-celebrates-soho-with-new-menu/'),
    ('swiftsoho', 'Legends', 2021, 12, '19 drinks based on the favourite tipples of famous figures, from Hemingway to Snoop Dogg, illustrated by Dan Collins.', ARRAY['Nightingale', 'Only in LA', 'Long Beach', 'Sunflower', 'Roadrunner']::text[], 'https://www.thespiritsbusiness.com/2021/12/new-swift-menu-spotlights-go-to-cocktails-of-famous-faces/'),
    ('swiftsoho', 'Postcards from Swift', 2023, NULL, '20 drinks drawn from the team''s personal travel memories, with illustrations by Helena Bonastre.', '{}'::text[], 'https://drinksint.com/menu-of-the-month-postcards-from-swift/'),
    ('swiftsoho', 'Soho menu (2024)', 2024, 11, '20 drinks inspired by Soho''s West End surroundings, with artwork by Dan Collins, alongside Swift classics.', ARRAY['Pantomime', 'Cyclorama', 'Irish Coffee', 'White Water', 'Imperial Gimlet', 'Rigoletto']::text[], 'https://drinksint.com/swift-soho-introduces-new-menu/'),
    ('swiftsoho', 'Present', 2025, 11, 'Menu for the bar''s tenth year looking back over its catalogue, in four sections: Bright, Delicate, Rich and Stiff.', ARRAY['Kew Gardens', 'Destination Tokyo', 'Irish Coffee', 'Praline Flip', 'White Water']::text[], 'https://www.thespiritsbusiness.com/2025/11/swift-soho-enters-10th-year-with-new-menu/'),
    ('littlereddoor_paris', 'Third menu (spring-summer 2014)', 2014, NULL, 'Third seasonal list (the bar then changed menus twice a year), running from light aperitif drinks to digestif styles.', '{}'::text[], 'https://web.archive.org/web/20160201154639/http://lrdparis.com/wp-content/uploads/2015/11/lrd_full-media-press-kit.pdf'),
    ('littlereddoor_paris', 'The Evocative Menu', 2016, 4, 'Eleven drinks shown only as artworks, each made by an artist who tasted the cocktail; no names or descriptions.', '{}'::text[], 'https://thecocktaillovers.com/the-new-evocative-menu-at-little-red-door-paris/'),
    ('littlereddoor_paris', 'A Menu of Applied Architecture', 2017, NULL, 'Eleven drinks, each tied to an architectural movement from primitivism to deconstructivism, served in matching vessels.', ARRAY['Order, Colour and Geometry', 'Shape follows function']::text[], 'https://barstalker.de/en/little-red-door-architecture-inspired-drinks/'),
    ('littlereddoor_paris', 'The Menu of Universal Values', 2018, 5, 'Drinks built on Schwartz''s theory of basic human values, presented as an illustrated storybook with bespoke glassware.', ARRAY['Tradition', 'Self Direction', 'Hedonism', 'Stimulation', 'Balance', 'Achievement', 'Security', 'Benevolence', 'Conformity', 'Strength']::text[], 'https://thecocktaillovers.com/the-new-menu-at-little-red-door-paris-introducing-the-menu-of-universal-values/'),
    ('littlereddoor_paris', 'A Way With Words', 2019, NULL, 'Ten untranslatable words from around the world, each inspiring a cocktail; printed in French and English.', '{}'::text[], 'https://barmag.fr/wp-content/uploads/2020/06/Press-Release-Little-Red-Door-Dont-Judge-A-Door-By-Its-Color-TIM.pdf'),
    ('littlereddoor_paris', 'Don''t Judge A Door By Its Colour', 2020, 3, 'Study of flavour versus sensation: each ingredient paired with a drink that has the sensation but not the flavour, and vice versa.', ARRAY['Coffee Without Bitter', 'Bitter Without Coffee', 'Mushroom Without Umami', 'Umami Without Mushroom', 'Honey Without Sweet', 'Sweet Without Honey']::text[], 'https://barmag.fr/wp-content/uploads/2020/06/Press-Release-Little-Red-Door-Dont-Judge-A-Door-By-Its-Color-TIM.pdf'),
    ('littlereddoor_paris', 'Grounded', 2021, 9, 'Ten cocktails each built on one ingredient from a named French farmer, pictured in a book-style menu; start of the farm-to-glass era.', ARRAY['Walnut', 'Lavender', 'Crème Fraîche', 'Olives from Nyons', 'Lemon']::text[], 'https://www.sortiraparis.com/en/where-to-eat-in-paris/bars-cafes/articles/260626-the-little-red-door-unveils-a-new-cocktail-list-shining-a-light-on-10-french-producers'),
    ('littlereddoor_paris', 'Flourish', 2022, 7, 'Farm-to-glass follow-up to Grounded: produce turned into house mistelles, vermouths and liqueurs, with zero-ABV and CBD options.', ARRAY['Carrot', 'Raspberry']::text[], 'https://thedramattic.com/2022/07/06/little-red-door-launches-new-menu-flourish/'),
    ('littlereddoor_paris', 'Farm to Glass rotating menu', 2023, 10, 'Themed menus dropped for six drinks rotating through the year plus four hyper-seasonal serves, also sold as a tasting menu.', '{}'::text[], 'https://drinksint.com/news/fullstory.php/aid/10865/Little_Red_Door_drops_conceptual_menus.html'),
    ('littlereddoor_paris', 'Twisted Mirrors', 2024, 7, 'Reopening menu under new owners: classics bent like funhouse mirrors, all French ingredients, each with a carbon-footprint score.', ARRAY['Negroni Sbagliato', 'Sbagliato Sbagliato', 'Margarita', 'Pêche Marguerite', 'Fish House Punch', 'Poisson Maison Melon']::text[], 'https://www.thespiritsbusiness.com/2024/08/little-red-door-debuts-reopening-cocktail-menu/'),
    ('littlereddoor_paris', 'Agri/Culture', 2025, 9, 'Eleven drinks, each on a sustainable farming practice (agroforestry, aquaponics, permaculture) with a French ambassador ingredient.', ARRAY['Carbone', 'Régénératrice', 'Agroforesterie', 'Aquaponie', 'Serre Solaire', 'Aquaculture', 'Urbaine']::text[], 'https://www.thespiritsbusiness.com/2025/09/little-red-door-creates-regenerative-farming-menu/'),
    ('devie.bar', 'Comptoir De Vie opening tasting menu', 2025, 3, 'Hyper-seasonal restaurant tasting menu with small paired cocktails made in-house from French produce, served without ice.', ARRAY['Sgroppino', 'Beetroot']::text[], 'https://www.thespiritsbusiness.com/2025/03/alexis-francis-and-barney-okane-on-bringing-de-vie-to-life/'),
    ('devie.bar', 'Bar De Vie opening menu', 2025, 9, 'Cellar bar menu of seasonal cocktails, fruit wines and digestifs upcycled from kitchen and bar waste, in a limestone cellar.', '{}'::text[], 'https://drinksint.com/news/fullstory.php/aid/11966/Exclusive:_Bar_De_Vie_opens_in_Paris.html'),
    ('harrysbar_theoriginal', 'House cocktail list (permanent)', 1911, 11, 'Permanent list of 400-plus classics, many born at the bar, kept since it opened on Thanksgiving 1911 rather than rotated as editions.', ARRAY['Bloody Mary', 'Side Car', 'French 75', 'Boulevardier', 'James Bond']::text[], 'https://www.harrysbar.com/'),
    ('barhemingway', 'The Hemingway Star No. 105', 2010, 11, 'Issue 105 of the bar''s newspaper-style menu: frozen Martinis, a make-your-own Margarita, Calvados drinks and Colin Field signatures.', ARRAY['Raspberry Martini', 'Ritzini', 'Jerry Thomas Martini', 'Platinum Bullet', 'Tomato-tini', 'Brazilita', 'Havatini', 'Poire Victoire', 'Kauda-Lee', 'Piranha', 'Luther III', 'Hell Raiser', 'Jeff 1', 'Highland Cream', 'Robertino', 'Leperliac', 'Serendipity', 'Brick Wall']::text[], 'https://web.archive.org/web/20120516164223/http://www.ritzparis.com/medias/documents/The_Hemingway_Star_Juillet.pdf'),
    ('candelariaparis', 'Opening menu', 2011, 3, 'Hidden agave-led bar behind a taqueria: about ten signatures plus guest drinks from New York bartenders.', ARRAY['La Guêpe Verte']::text[], 'https://52martinis.com/taco-cocktail-adventures-candelaria/'),
    ('candelariaparis', 'Summer 2015 menu', 2015, 7, 'Summer house cocktails with agave, aquavit and amaro accents next to Candelaria classics and alcohol-free drinks.', ARRAY['Luna Silvestre', 'Un Rhum à l''Amer', 'La Dolce Vita', 'Orange Is the New Black', 'Mother''s Julep', 'El Gallo de Oro', 'Mission Impossible', 'Rosemary''s Baby']::text[], 'https://web.archive.org/web/20160615003622/http://www.quixotic-projects.com:80/wp-content/uploads/2015/08/menu_candelaria_summer_2015.pdf'),
    ('candelariaparis', 'August 2016 menu', 2016, 8, 'Late-summer list of new agave and mezcal creations beside the Guêpe Verte and other house classics.', ARRAY['Domino', 'Le Rêve de Camus', 'Amor & Deudas', 'Minas Gift', 'El Gallo de Oro', 'Melissa', 'Al Son de la Batanga']::text[], 'https://web.archive.org/web/20160909214227/http://www.quixotic-projects.com:80/wp-content/uploads/2016/08/Candelaria-Menu-5-Aout.pdf'),
    ('candelariaparis', 'Leyendas', 2017, 3, 'Illustrated menu where each drink tells a Latin American folk legend, from La Llorona to the Chupacabras.', ARRAY['La Llorona', 'El Chupacabras', 'La Pata Sola', 'Pombero', 'Las Ciguapas', 'El Caipora', 'Lari-Lari', 'La Dulce Xali']::text[], 'https://web.archive.org/web/20170518211818/http://www.quixotic-projects.com:80/wp-content/uploads/2017/03/MENU-LEYENDAS-CANDELARIA-MARS-2103-Version-Finale.pdf'),
    ('candelariaparis', 'Autumn 2021 cocktail menu', 2021, 9, 'Ten seasonal house creations built on infused spirits, cordials and ferments, alongside house classics and alcohol-free drinks.', ARRAY['Fig Lyf', 'El Campo', 'Mango-Bango', 'Something Interesting', 'Moustachio-Pistachio', 'Boy With Pear', 'L''Amour en Cage', 'The Ambassador''s Party', 'Banoffee', 'Just Like Mama Used To Make']::text[], 'https://web.archive.org/web/20211109193447/https://www.candelaria-paris.com/s/MENUS-FOR-WEB.pdf'),
    ('experimentalcocktailclub', 'November 2023 menu', 2023, 11, 'Nine house signatures plus the bar''s standing Old Cuban and Experience 1 and a barrel-aged cocktail.', ARRAY['Kombuchita', 'Guajaca Del Arte', 'Loreto', 'Sicilian Bomber', 'PB&J', 'Kiwipedia', 'Tafé', 'Orchard In Da House', 'Tatoshu']::text[], 'https://assets-global.website-files.com/651df5fae24343b10b9d6649/656765606e8c2a8c5101470d_MENU%20ECC%20NOV%202023.pdf'),
    ('experimentalcocktailclub', 'Reopening menu', 2024, 6, 'New list for the bar''s reopening, keeping the Old Cuban and Experience 1 alongside fresh signatures.', ARRAY['The Polite Cosmo', 'Abré-té-Sesamo', 'Altiplanos', 'Bananarama', 'Isola Bella', 'Petit Pommeau', 'El Chapulin', 'Kokonatsu', 'Pink Power', 'Rosalia']::text[], 'https://cdn.prod.website-files.com/651df5fae24343b10b9d6649/665831d37fb87d1023114f9a_CARTE%20ECC%20REOUVERTURE.pdf'),
    ('experimentalcocktailclub', 'November 2024 menu', 2024, 11, 'Autumn-winter signatures with a barrel-aged Improved Sazerac and two alcohol-free drinks.', ARRAY['Batango', 'Gama', 'Capre Del Mar', 'Mariposa', 'Misu', 'Smoky', 'Banco !', 'Vice / Versa', 'Amari''to', 'Yessi''r']::text[], 'https://cdn.prod.website-files.com/651df5fae24343b10b9d6649/6749f78fbd1531d132826a5c_MENU%20ECC%20PARIS%20NOV%202024%20WEB%20(2).pdf'),
    ('experimentalcocktailclub', 'May 2025 menu', 2025, 5, 'Spring-summer signatures ranging from a Nordic tiki drink to a Paris-Bangkok highball, plus a tomato Martini.', ARRAY['Agathe Power', 'Cocazzi', 'Peso Piuma', 'Nordik Tiki', 'Paris - Bangkok', 'Midnight Blackthorn', 'Poison Ivy', 'Maks Maï', 'Toma-Tini', 'Bobby Barrel Aged']::text[], 'https://cdn.prod.website-files.com/67b6f943f95bbe462f319fcc/6800e9437287ac6fbbc2ef53_MENU%20ECC%20PARIS%20MAI%202025%20WEB.pdf'),
    ('experimentalcocktailclub', 'October 2025 menu', 2025, 10, 'Autumn list in French and English with new signatures and riffs such as a Negroni twist and coconut espresso drink.', ARRAY['Porn Sam Martini', 'Hara Kita', 'Configroni', 'Boréal Carbone', 'Kentucky Fall', 'Papi à Malaga', 'Nabbia Breizh', 'Espresso Cocco', 'Old Datte', 'Asperula']::text[], 'https://cdn.prod.website-files.com/67b6f943f95bbe462f319fcc/69039e9438945b836a998ac6_MENU%20ECC%20PARIS%20OCT%202025%20WEB%20FR%20EN.pdf'),
    ('experimentalcocktailclub', 'April 2026 menu', 2026, 4, 'Spring list of new signatures around the permanent Old Cuban and Experience 1, plus a barrel-aged drink.', ARRAY['Ladys''ll Bug', 'Fly Me To Cancun', 'Erico Presto', 'Rice Rice Baby', 'Rose Paloma', 'Praia Da Julia', 'Check Yo Seb', 'Secco Verano', 'Mustache And Mullet', 'Barrel From The Barrel']::text[], 'https://cdn.prod.website-files.com/67b6f943f95bbe462f319fcc/69e8bd03f2f26e4b5b165ad6_MENU%20ECC%20PARIS%20AVRIL%202026%20WEB.pdf'),
    ('copperbay_paris', 'Opening menu', 2014, 9, 'Yacht-club themed cocktail and pastis bar opens near République; the opening list itself is not archived.', '{}'::text[], 'https://www.timeout.fr/paris/actualites/on-a-goute-en-exclusivite-la-carte-danniversaire-ultra-retro-du-copperbay-le-bar-a-cocktails-du-10e-060224'),
    ('copperbay_paris', 'Summer 2016 collection', 2016, 5, 'Mediterranean-leaning summer signatures, from a tomato-rocket Martini to a pastis-based Mauresco.', ARRAY['Roquettini', 'Remember Last Summer', 'Mauresco', 'Malgache Swizzle', 'Pleasant Hill', 'Muito Legal', 'Andalousie', 'C''est le Bouquet']::text[], 'http://www.copperbay.fr/img/pdf/carte_cocktail_ete_2016.pdf'),
    ('copperbay_paris', 'Summer 2017 collection', 2017, 5, 'Summer list of travel-inspired signatures, including a clarified punch served by the bowl.', ARRAY['Bob Lee Punch', 'Melonade', 'Ithaca Road', 'Smokey Monkey', 'Mermaid Gimlet', 'Orchata', 'Distrito']::text[], 'http://www.copperbay.fr/img/pdf/carte_ete_2017.pdf'),
    ('copperbay_paris', 'Summer 2018 collection', 2018, 5, 'Summer signatures crossing cuisines and places, from Turin-Casablanca bitters to a clear colada.', ARRAY['Casablanca Torino', 'Monkey in the Yard', 'O Perfume', 'Pimp My Paloma', 'Spring Pie', 'Garde la Pêche', 'Mr Seguin', 'Clear My Colada']::text[], 'http://www.copperbay.fr/img/pdf/carte_ete_2018.pdf'),
