    ('blackpearlfitzroy', 'Tourism menu (15th anniversary)', 2017, 6, 'Retro travel-style list that doubles as a map of the team''s favourite Melbourne bars and restaurants.', ARRAY['Javier', 'Wallbuilder', 'Three Drop Swizzle', 'The Strangelove Daisy', 'Harajuku Highball', 'The Bandersnatch', 'Cairo', 'Panacea', 'FOMO', 'The Intern']::text[], 'https://australianbartender.com.au/2017/06/21/new-black-pearl-cocktail-list/'),
    ('gimlet.melbourne', 'Opening menu', 2020, NULL, 'Classics with modern interpretations alongside house cocktails, developed during lockdown before the pandemic-era opening.', '{}'::text[], 'https://australianbartender.com.au/2022/06/14/we-hear-from-cameron-parish-gimlet-bar-manager-on-perfecting-the-gimlet-opening-in-a-pandemic-and-why-young-bartenders-should-enjoy-their-time-behind-the-stick/'),
    ('gimlet.melbourne', 'Cocktail list (Aug 2022)', 2022, 8, 'House drinks plus updated classics, a tableside Sazerac service and pastis service.', ARRAY['Golden Circle', 'Yuzu Alberto', 'Honeybee', 'Oak Hill Sour', 'Noisette', 'Tequila Buck', 'Collins', 'Sidecar', 'Alpino Fix', 'Brut Cocktail']::text[], 'http://web.archive.org/web/20220811055801/https://gimlet.melbourne/s/COCKTAIL.pdf'),
    ('gimlet.melbourne', 'Winter Cocktail List (2023)', 2023, 6, 'Winter house drinks with hazelnut, saffron, beeswax and pear, plus celebration serves like a Neroli French 75.', ARRAY['Hazelnut Martini', 'New Mexico', 'Golden Thread', 'Orchard Keeper', 'Southern Buck', 'Punch', 'Maison Charles']::text[], 'http://web.archive.org/web/20230605220750/https://gimlet.melbourne/s/Winter-Cocktail-List.pdf'),
    ('gimlet.melbourne', 'Spring Cocktail List (2026)', 2026, 9, 'Spring house drinks built on rhubarb, quince and pear, with luxe ''something to celebrate'' serves.', ARRAY['Rhubarb Spritz', 'Quince Martinez', 'Sauvage Cooler', 'Bravo', 'Rum Barrel', 'Triple Dry Martini', 'Champagne Cocktail', 'Latin Quarter', 'Canal Street']::text[], 'https://gimlet.melbourne/s/Spring-Cocktail-List.pdf'),
    ('apolloinn.bar', 'Opening menu', 2023, 6, 'Old-world European classics with new-world polish, four styles of Martini and a few signatures.', ARRAY['Lucien Gaudin', 'Picon Bière', 'Champagne Royale']::text[], 'https://australianbartender.com.au/2023/07/26/apollo-inn-two-cocktail-recipes-from-the-new-cocktail-bar-from-the-team-behind-gimlet/'),
    ('apolloinn.bar', 'Night Cap menu', 2025, 9, 'Three late-night after-dinner drinks served from 9pm alongside chocolate profiteroles.', ARRAY['Midnight Over Madeira', 'Braulio Shakerato', 'Caffé Frappé']::text[], 'https://australianbartender.com.au/2025/09/25/apollo-inn-launches-new-night-cap-menu/'),
