    ('goodwater.melbourne', 'Mixed drinks list (May 2024)', 2024, 5, 'American-whiskey bar''s early seasonal mixed drinks next to house signatures like a nitro Martini and Champagne Old Fashioned.', ARRAY['Southern Season', 'The Last Strawb', 'Spanish Moss', 'Four Hundred Rabbits', 'Pony Up', 'Bad Water', 'Kentucky Nitro Martini']::text[], 'https://goodwater.melbourne/wp-content/uploads/2024/05/Goodwater-Drinks-18-May.pdf'),
    ('goodwater.melbourne', 'Mixed drinks list (April 2025)', 2025, 4, 'Refreshed seasonal mixed drinks around the bar''s standing whiskey classics.', ARRAY['Chrysanthemum Spirit', 'Island Time', 'Side Bet', 'Nature Boy']::text[], 'https://goodwater.melbourne/wp-content/uploads/2025/04/Goodwater-Drinks-17-April-1.pdf'),
    ('goodwater.melbourne', 'Mixed drinks list (June 2025)', 2025, 6, 'Winter rotation of the seasonal mixed drinks, keeping Side Bet.', ARRAY['Park Date', 'Sundown', 'Recliner', 'Side Bet']::text[], 'https://goodwater.melbourne/wp-content/uploads/2025/07/Drinks-11-June-1.pdf'),
    ('goodwater.melbourne', 'House and classics list (July 2026)', 2026, 7, 'Restructured list: a larger House section of originals, a Classics section and no-booze drinks.', ARRAY['Nouveau Nouveau', 'Free Practice', 'Half Time', 'Cabana', 'Sundown', 'Twister', 'Surf Club', 'Spagliato Spagliato', 'Dustbowl Negroni', 'Bright Eyes', 'Golden Cadillac Milk Punch']::text[], 'https://goodwater.melbourne/wp-content/uploads/2026/07/Drinks.pdf'),
    ('pendant.publicbar', 'Opening menu', 2025, 5, 'Six-drink list led by a freezer Martini and cognac Old Fashioned, plus four rotating slots (spritz, sour, dark, stirred).', '{}'::text[], 'https://www.broadsheet.com.au/melbourne/bars/pendant-public-bar'),
    ('handsdownmelbourne', 'Opening menu', 2025, NULL, 'About 12 vermouth- and sherry-led Continental cocktails: spritzes, fruity, salty and slushie sections.', '{}'::text[], 'https://www.broadsheet.com.au/melbourne/bars/hands-down'),
    ('handsdownmelbourne', 'Winter Menu', 2026, NULL, 'Winter list split into easy spritzy, fruity and fortified, salty and stirred, and hot and creamy drinks.', ARRAY['Scrumpy Apple Spritz', 'Butter & Brine', 'Hands Down Highball', 'Tall Fruity Little Bit Spicy', 'Pastis Swizzle', 'Winter Sherry Cobbler', 'Mandarin Sour', 'Marianito', 'Fifty-Fifty Martini', 'Caffè Italiano', 'Hot Buttered Agave', 'Coconut & Pastis Ramos Fizz']::text[], 'https://www.dropbox.com/scl/fi/9ka3kvgcavftagnhglwq4/Winter-Menu.pdf?rlkey=6uvbbkg6rrnxl6g2hmkzfdarh&dl=0'),
    ('bar1806', 'History of the cocktail menu', 2007, NULL, 'Opening concept: a classic for each decade since 1806, each with its history, plus originals.', '{}'::text[], 'https://www.broadsheet.com.au/melbourne/bars/1806'),
    ('bar1806', 'Theatre menu', 2024, 12, 'Tribute to the theatre in five chapters: Kabuki Fantasy, Tribal Tragedy, Drama of Love, Dreams of Broadway, Everybody''s Laughing.', ARRAY['Shibai Ukie', 'Game of Zen', 'Breath of Life', 'A Fiery Secret', 'A Phantom Affair', 'Panache', 'Something Is Coming', 'Rose Rouge', 'Playing with Fire', 'Midsummer Wedding']::text[], 'https://cdn.prod.website-files.com/6759032ad003dab7a141781f/6760f9699788a37e1c1ff5e0_1806-website-menu.pdf'),
    ('bar1806', 'Character archetypes menu', 2025, 11, 'Signatures each tied to a story archetype (the Chosen One, the Wise Mentor, the Trickster), plus a Martini flight.', ARRAY['Hope''s Ember', 'Ashes will Bloom', 'A Promise to Keep', 'Break in the Wall', 'The Last Soliloquy', 'Called Back', 'A Reason to Stay', 'Yūrei', 'Burn', 'Behind Kind Eyes', 'Fixed at the Joints']::text[], 'https://cdn.prod.website-files.com/6759032ad003dab7a141781f/6913eb7b65e85239e5e39a5f_1806%20Cocktail%20Menu.pdf')
